async function getUser(id) {
  const hit = await cache.get(`user:${id}`);
  if (hit) return JSON.parse(hit);
  const user = await db.user(id);
  await cache.set(`user:${id}`, JSON.stringify(user), { ex: 300 });   // 5분
  return user;
}

// 갱신 시
async function updateUser(id, patch) {
  await db.update(id, patch);
  await cache.del(`user:${id}`);      // 지운다(갱신보다 지우기가 안전하다)
}
